
local coldsteelBG = {
	{name = 'whiteBG', color = 'FFFFFF', x = -2000, y = -2000, width = 6000, height = 6000, scaleX = 1, scaleY = 1, scrollX = 1, scrollY = 1, alpha = 1, front = false}
}

local colorEveryBeats = 4

function onCreate()
	for _, bg in ipairs(coldsteelBG) do
		makeLuaSprite(bg.name, nil, bg.x, bg.y)
		makeGraphic(bg.name, bg.width, bg.height, bg.color)
		scaleObject(bg.name, bg.scaleX, bg.scaleY)
		setScrollFactor(bg.name, bg.scrollX, bg.scrollY)
		setProperty(bg.name ..'.alpha', bg.alpha)
		addLuaSprite(bg.name, bg.front)
	end

	makeLuaSprite('grad', 'grad')
	scaleObject('grad', 3000, 1.5)
	screenCenter('grad')
	addLuaSprite('grad')
end

function onBeatHit()
	if curBeat % colorEveryBeats == 0 then 
		cancelTween('grad')
		setProperty('grad.color', getColorFromHex('FFB5F0'))
		doTweenColor('grad', 'grad', 'FFFFFF', 1, 'cubeOut')
	end
end

